const std = @import("std");

pub fn main() !void {
    var arr = [_]i32{ 64, 25, 12, 22, 11 };

    for (0..arr.len) |i| {
        var min_idx: usize = i;
        for (i + 1..arr.len) |j| {
            if (arr[j] < arr[min_idx]) {
                min_idx = j;
            }
        }
        const temp = arr[i];
        arr[i] = arr[min_idx];
        arr[min_idx] = temp;
    }

    for (arr) |val| std.debug.print("{} ", .{val});
    std.debug.print("\n", .{});
}
